// pages.tsx
"use client";

import React from 'react';
import Navbar from "./components/Navbar";
import styles from "./page.module.css";
import { useRouter } from 'next/navigation';
import Footer1 from './components/Footer1';

export default function Home() {
  const router = useRouter();

  const pushit = () => {
    // Suivre l'événement avec Google Analytics
    (window as any).gtag('event', 'click', {
      event_category: 'button',
      event_label: 'Découvrir Vyft',
      value: 1,
    });

    router.push("/produits/vyft");
  };

  return (
    <div>
      <div className={styles.container}>
        <Navbar />
        <main className={styles.main}>
          <h1 className={styles.header}>
            Bienvenue dans la nouvelle génération mondiale de l&apos;écologie circulaire dans l&apos;ère de l&apos;économie !
          </h1>
          <h2 className={styles.body}>
            Alors, qu&apos;un mirroir ne reflète que ce qui n&apos;est visible dans le plan du cycle du CO₂.
          </h2>
          <div className={styles.bodyattract}>
            <h2 className={styles.body}>
              Voici, notre premier produit encore en phase bêta, Vyft, une néobanque mais aussi une plateforme d&apos;échange d&apos;actif numérique¹ basée sur la fitness.
            </h2>
            <button className={styles.ActionEbutton} onClick={pushit}>
              <p className={styles.ActionE}>Découvrir Vyft</p>
            </button>
          </div>
        </main>
      </div>
      <div className={styles.container1}>
        <main className={styles.main}>
          <h1 className={styles.header}>
            Nous reconstruisons de zéro les solutions de demain afin de s&apos;unir pour l&apos;environnement.
          </h1>
          <h2 className={styles.bodymessage}>
            1. L&apos;investissement étant un cas de perte foncière, cela s&apos;applique à la néobanque.
          </h2>
        </main>
        <Footer1 />
      </div>
    </div>
  );
}